+package worker
+
+import (
+	"context"
+	"sync/atomic"
+	"time"
+)
+
+// DefaultInterval is how long an idle worker sleeps before it checks the queue again.
+const DefaultInterval = time.Second
+
+// Worker runs queued jobs one at a time. Each job takes several seconds.
+type Worker struct {
+	queue    *Queue
+	waiting  atomic.Bool
+	wake     chan struct{}
+	interval time.Duration
+	handle   func(Job)
+}
+
+// Run handles jobs until ctx ends.
+func (w *Worker) Run(ctx context.Context) {
+	for {
+		if job, ok := w.queue.Pop(); ok {
+			w.handle(job)
+			continue
+		}
+		w.waiting.Store(true)
+		select {
+		case <-ctx.Done():
+			return
+		case <-w.wake:
+		case <-time.After(w.interval):
+		}
+		w.waiting.Store(false)
+	}
+}
+
+// Submit queues job and wakes the worker when it waits.
+func (w *Worker) Submit(job Job) {
+	w.queue.Push(job)
+	if w.waiting.Load() {
+		select {
+		case w.wake <- struct{}{}:
+		default:
+		}
+	}
+}
